            raw.ids.push(id);
            raw.vectors.extend_from_slice(&vector);
            inserted += 1;
        }

        if inserted > 0 {
            self.update_official_cache_ready(raw.ids.len());
            self.dirty.store(true, Ordering::Release);
        }

        inserted
    }

