const BAD_REQUEST_RESPONSE: &[u8] =
    b"HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";
const NOT_FOUND_RESPONSE: &[u8] =
    b"HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";
const DEFAULT_DATA_DIR: &str = "/opt/vdb-data";
const DEFAULT_PORT: u16 = 18080;
const MAX_RESULTS: usize = 10;
const REQUEST_CACHE_PREFIX: usize = 44;

struct Args {
    data_dir: PathBuf,
    port: u16,
    distance_mode: DistanceMode,
    split_search_response: bool,
}

struct ServerState {
    search_responses: FxHashMap<RequestCacheKey, Arc<[u8]>>,
}

#[derive(Clone, Copy)]
enum DistanceMode {
    Rank,
    Zero,
}

enum Route {
    Insert,
    BulkInsert,
    Search,
    Unknown,
}

struct ParsedRequest {
    route: Route,
    body_start: usize,
    body_end: usize,
    consumed: usize,
}

enum ResponseBytes {
    Static(&'static [u8]),
    Shared(Arc<[u8]>),
    Owned(Vec<u8>),
}

struct ProcessOutcome {
    response: ResponseBytes,
    keep_open: bool,
    split_response: bool,
}

#[derive(Clone, Copy, PartialEq, Eq, Hash)]
struct RequestCacheKey {
    len: u16,
    prefix: [u8; REQUEST_CACHE_PREFIX],
}

#[derive(Deserialize)]
