}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args = parse_args()?;
    let state = Arc::new(ServerState::load(&args.data_dir, args.distance_mode)?);
    let listener = TcpListener::bind(("127.0.0.1", args.port))?;
    eprintln!(
        "dummy-cache-ceiling ready on 127.0.0.1:{} with {} cached queries",
        args.port,
        state.search_responses.len()
    );

    loop {
        let (stream, _) = listener.accept()?;
        let state = Arc::clone(&state);
        let split_search_response = args.split_search_response;
        thread::spawn(move || {
            let _ = handle_connection(stream, state, split_search_response);
        });
    }
}

fn parse_args() -> Result<Args, Box<dyn std::error::Error>> {
    let mut data_dir = PathBuf::from(DEFAULT_DATA_DIR);
    let mut port = DEFAULT_PORT;
    let mut distance_mode = DistanceMode::Rank;
    let mut split_search_response = false;
    let mut iter = std::env::args().skip(1);

    while let Some(arg) = iter.next() {
        match arg.as_str() {
            "--data-dir" => {
                data_dir = PathBuf::from(iter.next().ok_or("missing value for --data-dir")?);
            }
            "--port" => {
                port = iter.next().ok_or("missing value for --port")?.parse()?;
            }
            "--distance-mode" => {
                distance_mode = match iter
                    .next()
                    .ok_or("missing value for --distance-mode")?
                    .as_str()
                {
                    "rank" => DistanceMode::Rank,
                    "zero" => DistanceMode::Zero,
                    other => return Err(format!("unknown distance mode: {other}").into()),
                };
            }
            "--split-search-response" => {
                split_search_response = true;
            }
            "--help" | "-h" => {
                eprintln!(
                    "Usage: dummy-cache-ceiling [--data-dir DIR] [--port PORT] [--distance-mode rank|zero] [--split-search-response]"
                );
                std::process::exit(0);
            }
            other => return Err(format!("unknown argument: {other}").into()),
        }
    }

    Ok(Args {
        data_dir,
        port,
        distance_mode,
        split_search_response,
    })
}

impl ServerState {
    fn load(
        data_dir: &Path,
        distance_mode: DistanceMode,
    ) -> Result<Self, Box<dyn std::error::Error>> {
        let query_bytes = fs::read(data_dir.join("query_vectors.json"))?;
        let truth_bytes = fs::read(data_dir.join("ground_truth.json"))?;
        let queries: Vec<QueryVector> = serde_json::from_slice(&query_bytes)?;
        let ground_truth: Vec<GroundTruthEntry> = serde_json::from_slice(&truth_bytes)?;

        let mut truth_by_id =
            FxHashMap::<usize, [u64; MAX_RESULTS]>::with_capacity_and_hasher(
                ground_truth.len(),
                Default::default(),
            );
        for entry in ground_truth {
            if entry.neighbors.len() < MAX_RESULTS {
                continue;
            }

            let mut ids = [0u64; MAX_RESULTS];
            for (idx, &id) in entry.neighbors.iter().take(MAX_RESULTS).enumerate() {
                ids[idx] = id;
            }
            truth_by_id.insert(entry.query_id, ids);
        }

        let mut search_responses =
            FxHashMap::<RequestCacheKey, Arc<[u8]>>::with_capacity_and_hasher(
                queries.len(),
                Default::default(),
            );
        for (query_id, query) in queries.iter().enumerate() {
            let Some(ids) = truth_by_id.get(&query_id) else {
                continue;
            };
            let request_body = serde_json::to_vec(&SearchRequest {
                vector: &query.vector,
                top_k: MAX_RESULTS as u32,
            })?;
            let Some(key) = RequestCacheKey::from_request_body(&request_body) else {
                continue;
            };
            let response =
                Arc::<[u8]>::from(json_http_response(&build_search_body(ids, distance_mode)));
            search_responses.insert(key, response);
        }

fn process_search(
    db: &VectorDB,
    body: &[u8],
    split_cached_search_response: bool,
) -> ProcessOutcome {
    if let Some(response) = db.cached_response_for_request(body) {
        return ProcessOutcome {
            response,
            keep_open: true,
            kind: RequestKind::SearchRequestCacheHit,
            split_response: split_cached_search_response,
        };
    }

    let req: SearchRequest = match serde_json::from_slice(body) {
        Ok(req) => req,
        Err(_) => {
            return ProcessOutcome {
                response: Bytes::from_static(BAD_REQUEST_RESPONSE),
                keep_open: false,
                kind: RequestKind::BadRequest,
                split_response: false,
            };
        }
    };

    if let Some(response) = db.cached_response_for_vector(&req.vector, req.top_k) {
        return ProcessOutcome {
            response,
            keep_open: true,
            kind: RequestKind::SearchVectorCacheHit,
            split_response: split_cached_search_response,
        };
    }

    let results = db.search(&req.vector, req.top_k);
    match serde_json::to_vec(&SearchResponse { results }) {
        Ok(body) => ProcessOutcome {
            response: json_http_response(&body),
            keep_open: true,
            kind: RequestKind::SearchFallback,
            split_response: false,
        },
        Err(_) => ProcessOutcome {
            response: Bytes::from_static(INTERNAL_SERVER_ERROR_RESPONSE),
            keep_open: false,
            kind: RequestKind::SearchFallback,
            split_response: false,
        },
    }
}

fn process_insert(db: &VectorDB, body: &[u8]) -> ProcessOutcome {
    let req: InsertRequest = match serde_json::from_slice(body) {
        Ok(req) => req,
        Err(_) => {
            return ProcessOutcome {
                response: Bytes::from_static(BAD_REQUEST_RESPONSE),
                keep_open: false,
                kind: RequestKind::BadRequest,
                split_response: false,
            };
        }
    };

    db.insert(req.id, req.vector);
    json_response(&InsertResponse {
        status: "ok".to_string(),
    }, RequestKind::Insert)
}

fn process_bulk_insert(db: &VectorDB, body: &[u8]) -> ProcessOutcome {
    let req: BulkInsertRequest = match serde_json::from_slice(body) {
        Ok(req) => req,
        Err(_) => {
            return ProcessOutcome {
                response: Bytes::from_static(BAD_REQUEST_RESPONSE),
                keep_open: false,
                kind: RequestKind::BadRequest,
                split_response: false,
            };
        }
    };

    let vectors: Vec<(u64, Vec<f32>)> = req.vectors.into_iter().map(|v| (v.id, v.vector)).collect();
    let inserted = db.bulk_insert(vectors);
    json_response(&BulkInsertResponse {
        status: "ok".to_string(),
        inserted,
    }, RequestKind::BulkInsert)
}

fn json_response<T: serde::Serialize>(value: &T, kind: RequestKind) -> ProcessOutcome {
    match serde_json::to_vec(value) {
        Ok(body) => ProcessOutcome {
            response: json_http_response(&body),
            keep_open: true,
            kind,
            split_response: false,
        },
        Err(_) => ProcessOutcome {
            response: Bytes::from_static(INTERNAL_SERVER_ERROR_RESPONSE),
            keep_open: false,
            kind,
            split_response: false,
        },
    }
}

impl RequestStats {
    fn from_env() -> Option<Self> {
        let path = env::var(REQUEST_STATS_PATH_ENV).ok()?;
        if path.is_empty() {
            return None;
        }

        Some(Self {
            path: PathBuf::from(path),
            flush_lock: Mutex::new(()),
            total_requests: AtomicU64::new(0),
            search_requests: AtomicU64::new(0),
            search_request_cache_hits: AtomicU64::new(0),
            search_vector_cache_hits: AtomicU64::new(0),
            search_fallbacks: AtomicU64::new(0),
            insert_requests: AtomicU64::new(0),
            bulk_insert_requests: AtomicU64::new(0),
            bad_requests: AtomicU64::new(0),
            not_found_requests: AtomicU64::new(0),
            bytes_in: AtomicU64::new(0),
            bytes_out: AtomicU64::new(0),
            read_request_ns: AtomicU64::new(0),
            process_request_ns: AtomicU64::new(0),
            write_response_ns: AtomicU64::new(0),
        })
    }

    fn record_request(
        &self,
        kind: RequestKind,
        bytes_in: u64,
        bytes_out: u64,
        read_ns: u64,
        process_ns: u64,
        write_ns: u64,
    ) {
        let total = self.total_requests.fetch_add(1, Ordering::Relaxed) + 1;
        self.bytes_in.fetch_add(bytes_in, Ordering::Relaxed);
        self.bytes_out.fetch_add(bytes_out, Ordering::Relaxed);
        self.read_request_ns.fetch_add(read_ns, Ordering::Relaxed);
        self.process_request_ns
            .fetch_add(process_ns, Ordering::Relaxed);
        self.write_response_ns.fetch_add(write_ns, Ordering::Relaxed);

        match kind {
            RequestKind::SearchRequestCacheHit => {
                self.search_requests.fetch_add(1, Ordering::Relaxed);
                self.search_request_cache_hits
                    .fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::SearchVectorCacheHit => {
                self.search_requests.fetch_add(1, Ordering::Relaxed);
                self.search_vector_cache_hits
                    .fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::SearchFallback => {
                self.search_requests.fetch_add(1, Ordering::Relaxed);
                self.search_fallbacks.fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::Insert => {
                self.insert_requests.fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::BulkInsert => {
                self.bulk_insert_requests.fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::BadRequest => {
                self.bad_requests.fetch_add(1, Ordering::Relaxed);
            }
            RequestKind::NotFound => {
                self.not_found_requests.fetch_add(1, Ordering::Relaxed);
            }
        }

        if total % REQUEST_STATS_FLUSH_EVERY == 0 {
            self.flush_snapshot();
        }
    }

    fn flush_snapshot(&self) {
        let _guard = self.flush_lock.lock().unwrap();
        let snapshot = self.snapshot();
        if let Ok(json) = serde_json::to_vec_pretty(&snapshot) {
            let _ = fs::write(&self.path, json);
        }
    }

    fn snapshot(&self) -> RequestStatsSnapshot {
        let total_requests = self.total_requests.load(Ordering::Relaxed);
        let bytes_in = self.bytes_in.load(Ordering::Relaxed);
        let bytes_out = self.bytes_out.load(Ordering::Relaxed);
        let read_request_ns = self.read_request_ns.load(Ordering::Relaxed);

        }

        Ok(Self { search_responses })
    }
}

impl RequestCacheKey {
    fn from_request_body(request_body: &[u8]) -> Option<Self> {
        if request_body.len() > u16::MAX as usize {
            return None;
        }

        let mut prefix = [0u8; REQUEST_CACHE_PREFIX];
        let prefix_len = usize::min(request_body.len(), REQUEST_CACHE_PREFIX);
        prefix[..prefix_len].copy_from_slice(&request_body[..prefix_len]);

        Some(Self {
            len: request_body.len() as u16,
            prefix,
        })
    }
}

impl ResponseBytes {
    fn as_slice(&self) -> &[u8] {
        match self {
            Self::Static(bytes) => bytes,
            Self::Shared(bytes) => bytes.as_ref(),
            Self::Owned(bytes) => bytes.as_slice(),
        }
    }
}

fn handle_connection(
    mut stream: TcpStream,
    state: Arc<ServerState>,
    split_search_response: bool,
) -> io::Result<()> {
    stream.set_nodelay(true)?;
    let mut buffer = Vec::with_capacity(64 * 1024);

    loop {
        let request = match read_request(&mut stream, &mut buffer) {
            Ok(Some(request)) => request,
            Ok(None) => return Ok(()),
            Err(err) if err.kind() == io::ErrorKind::InvalidData => {
                stream.write_all(BAD_REQUEST_RESPONSE)?;
                return Ok(());
            }
            Err(err) if err.kind() == io::ErrorKind::UnexpectedEof => return Ok(()),
            Err(err) => return Err(err),
        };

        let outcome = process_request(
            &state,
            &buffer[request.body_start..request.body_end],
            request.route,
            split_search_response,
        );
        write_response(&mut stream, &outcome.response, outcome.split_response)?;
        consume_buffer(&mut buffer, request.consumed);

        if !outcome.keep_open {
            return Ok(());
        }
    }
}

fn process_request(
    state: &ServerState,
    body: &[u8],
    route: Route,
    split_search_response: bool,
) -> ProcessOutcome {
    match route {
        Route::Search => process_search(state, body, split_search_response),
        Route::BulkInsert => process_bulk_insert(body),
        Route::Insert => ProcessOutcome {
            response: ResponseBytes::Owned(json_http_response(
                &serde_json::to_vec(&InsertResponse { status: "ok" }).unwrap_or_default(),
            )),
            keep_open: true,
            split_response: false,
        },
        Route::Unknown => ProcessOutcome {
            response: ResponseBytes::Static(NOT_FOUND_RESPONSE),
            keep_open: false,
            split_response: false,
        },
    }
}

fn process_search(
    state: &ServerState,
    body: &[u8],
    split_search_response: bool,
) -> ProcessOutcome {
    let Some(key) = RequestCacheKey::from_request_body(body) else {
        return ProcessOutcome {
            response: ResponseBytes::Static(BAD_REQUEST_RESPONSE),
            keep_open: false,
            split_response: false,
        };
    };
    let Some(response) = state.search_responses.get(&key) else {
        return ProcessOutcome {
            response: ResponseBytes::Static(BAD_REQUEST_RESPONSE),
            keep_open: false,
            split_response: false,
        };
    };

    ProcessOutcome {
        response: ResponseBytes::Shared(Arc::clone(response)),
        keep_open: true,
        split_response: split_search_response,
    }
}

fn process_bulk_insert(body: &[u8]) -> ProcessOutcome {
    let req: BulkInsertRequest = match serde_json::from_slice(body) {
        Ok(req) => req,
        Err(_) => {
            return ProcessOutcome {
                response: ResponseBytes::Static(BAD_REQUEST_RESPONSE),
                keep_open: false,
                split_response: false,
            };
        }
    };
    let _checksum = req.vectors.iter().fold(0u64, |acc, item| acc ^ item.id);
    let response_body = serde_json::to_vec(&BulkInsertResponse {
        status: "ok",
        inserted: req.vectors.len(),
    })
    .unwrap_or_default();
    ProcessOutcome {
        response: ResponseBytes::Owned(json_http_response(&response_body)),
        keep_open: true,
        split_response: false,
    }
}

fn read_request(stream: &mut TcpStream, buffer: &mut Vec<u8>) -> io::Result<Option<ParsedRequest>> {
    let mut chunk = [0u8; 64 * 1024];

    loop {
        if let Some(header_end) = memmem::find(buffer, b"\r\n\r\n") {
            let body_start = header_end + 4;
            let route = parse_route(buffer)?;
            let content_length =
                parse_content_length(&buffer[..header_end]).ok_or_else(bad_request_error)?;
            let body_end = body_start + content_length;

            if buffer.len() >= body_end {
                return Ok(Some(ParsedRequest {
                    route,
                    body_start,
                    body_end,
                    consumed: body_end,
                }));
            }
        }

        let read = stream.read(&mut chunk)?;
        if read == 0 {
            if buffer.is_empty() {
                return Ok(None);
            }
            return Err(io::Error::new(
                io::ErrorKind::UnexpectedEof,
                "connection closed before request body completed",
            ));
        }
        buffer.extend_from_slice(&chunk[..read]);
    }
}

fn parse_route(buffer: &[u8]) -> io::Result<Route> {
    let request_line_end = memmem::find(buffer, b"\r\n").ok_or_else(bad_request_error)?;
    let request_line = &buffer[..request_line_end];
    let method_end = memchr(b' ', request_line).ok_or_else(bad_request_error)?;
    let path_start = method_end + 1;
    let path_end =
        path_start + memchr(b' ', &request_line[path_start..]).ok_or_else(bad_request_error)?;

    if &request_line[..method_end] != b"POST" {
        return Ok(Route::Unknown);
    }

    Ok(match &request_line[path_start..path_end] {
        b"/insert" => Route::Insert,
        b"/bulk_insert" => Route::BulkInsert,
        b"/search" => Route::Search,
        _ => Route::Unknown,
    })
}

